+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+const { cal } = ChromeUtils.importESModule(
+  "resource:///modules/calendar/calUtils.sys.mjs"
+);
+
+/**
+ * Calendar data that can be stored in Redux.
+ *
+ * @typedef {object} CalendarEventCalendar
+ * @property {string} id - The calendar ID.
+ * @property {string} name - The calendar name.
+ * @property {string} color - The calendar color.
+ */
+
+/**
+ * Copy the display data without retaining the calendar.
+ *
+ * @param {calICalendar} calendar
+ * @returns {CalendarEventCalendar}
+ */
+export function snapshotCalendar(calendar) {
+  return {
+    id: calendar.id,
+    name: calendar.name,
+    color: calendar.getProperty("color") || "#a8c2e1",
+  };
+}
+
+/**
+ * Whether the user can move this whole event to another calendar.
+ *
+ * @param {calIEvent} event
+ * @returns {boolean}
+ */
+export function canMoveCalendarEvent(event) {
+  return (
+    !event.recurrenceId &&
+    cal.acl.isCalendarWritable(event.calendar) &&
+    cal.acl.userCanModifyItem(event) &&
+    cal.acl.userCanDeleteItemsFromCalendar(event.calendar) &&
+    !cal.itip.isInvitation(event)
+  );
+}
+
+/**
+ * Returns display data for calendar choices and a supplied default calendar.
+ *
+ * Filters `calendars` to visible, writable event calendars with add permission.
+ * Orders `calendars` by `calendar.list.sortOrder`.
+ * The `defaultCalendar` snapshot can describe a calendar outside `calendars`.
+ *
+ * @param {?string} [defaultCalendarId=null] - The host window's default calendar
+ *   ID.
+ * @returns {Promise<{calendars: CalendarEventCalendar[], defaultCalendar: ?CalendarEventCalendar}>}
+ *   Calendar choices and the matching default calendar. If the caller omits
+ *   the ID or no calendar matches, `defaultCalendar` is null.
+ */
+export async function loadCalendarOptions(defaultCalendarId = null) {
+  const calendars = cal.manager.getCalendars();
+  const defaultCalendar = calendars.find(
+    calendar => calendar.id == defaultCalendarId
+  );
+
+  const order = new Map(
+    Services.prefs
+      .getStringPref("calendar.list.sortOrder", "")
+      .split(" ")
+      .map((id, index) => [id, index])
+  );
+
+  const usable = calendars.filter(
+    calendar =>
+      calendar.getProperty("calendar-main-in-composite") &&
+      cal.acl.isCalendarWritable(calendar) &&
+      cal.acl.userCanAddItemsToCalendar(calendar) &&
+      calendar.getProperty("capabilities.events.supported") !== false
+  );
+  usable.sort(
+    (first, second) =>
+      (order.get(first.id) ?? Infinity) - (order.get(second.id) ?? Infinity)
+  );
+
+  return {
+    calendars: usable.map(snapshotCalendar),
+    defaultCalendar: defaultCalendar ? snapshotCalendar(defaultCalendar) : null,
+  };
+}
