+
+import { createSlice } from "moz-src:///comm/third_party/redux/redux-toolkit/redux-toolkit.mjs";
+import { rootReducer } from "moz-src:///comm/mail/base/content/state/store.mjs";
+import { updateSection } from "./calendarEventDraftSlice.mjs";
+
+/**
+ * Display data and move permission for one create or edit operation.
+ *
+ * @typedef {object} CalendarEventCalendarState
+ * @property {number} generation - The operation number within this dialog.
+ * @property {CalendarEventCalendar[]} calendars - Usable destination calendars.
+ * @property {?CalendarEventCalendar} calendar - The initial calendar, including
+ *   an unavailable calendar that must still be displayed.
+ * @property {boolean} canChange - Whether this operation permits selection.
+ */
+
+export const calendarEventCalendarSlice = createSlice({
+  name: "calendarEventCalendar",
+  initialState: { sessions: {} },
+  reducers: {
+    clearCalendarSelection(state, { payload: { sessionKey } }) {
+      delete state.sessions[sessionKey];
+    },
+    setCalendarSelection(state, { payload: { sessionKey, ...selection } }) {
+      state.sessions[sessionKey] = structuredClone(selection);
+    },
+  },
+  selectors: {
+    selectCalendarSelection: (state, sessionKey) =>
+      state.sessions[sessionKey] ?? null,
+  },
+});
+
+const injectedSlice = calendarEventCalendarSlice.injectInto(rootReducer);
+export const { selectCalendarSelection } = injectedSlice.selectors;
+export const { clearCalendarSelection, setCalendarSelection } =
+  calendarEventCalendarSlice.actions;
+
+/**
+ * Change only the current draft's calendar. Ignore old operations and options
+ * that the current operation does not offer.
+ *
+ * @param {object} selection
+ * @param {string} selection.sessionKey - The dialog key.
+ * @param {number} selection.generation - The operation that showed the option.
+ * @param {string} selection.calendarId - The chosen calendar ID.
+ * @returns {Function} A Redux action that checks current state before updating.
+ */
+export function changeCalendar({ sessionKey, generation, calendarId }) {
+  return (dispatch, getState) => {
+    const selection = selectCalendarSelection(getState(), sessionKey);
+    if (
+      selection?.generation !== generation ||
+      !selection.canChange ||
+      !selection.calendars.some(calendar => calendar.id == calendarId)
+    ) {
+      return;
+    }
+
+    dispatch(
+      updateSection({ sessionKey, section: "calendar", patch: { calendarId } })
+    );
+  };
+}
