+  for (const dark of [0, 1]) {
+    await SpecialPowers.pushPrefEnv({
+      set: [["ui.systemUsesDarkTheme", dark]],
+    });
+    await TestUtils.waitForCondition(
+      () =>
+        browser.contentWindow.matchMedia("(prefers-color-scheme: dark)")
+          .matches == !!dark,
+      "The requested color scheme reaches the content window"
+    );
+
+    Assert.equal(
+      browser.contentWindow.matchMedia("(prefers-color-scheme: dark)").matches,
+      !!dark,
+      "The test should render the requested color scheme"
+    );
+
+    for (const density of ["compact", "normal", "touch"]) {
+      doc.documentElement.setAttribute("uidensity", density);
+      for (const direction of ["ltr", "rtl"]) {
+        doc.documentElement.dir = direction;
+
+        const selectRect = select.getBoundingClientRect();
+        const swatchRect = swatch.getBoundingClientRect();
+
+        Assert.greater(
+          selectRect.width,
+          0,
+          `${density} ${direction} should have a visible selector`
+        );
+        Assert.greaterOrEqual(
+          swatchRect.left,
+          selectRect.left,
+          "Color should stay inside the control"
+        );
+        Assert.lessOrEqual(
+          swatchRect.right,
+          selectRect.right,
+          "Color should stay inside the control"
+        );
+        Assert.equal(
+          select.selectedOptions[0].textContent,
+          defaultCalendar.name,
+          "The selected option should retain the calendar name"
+        );
+
+        select.focus();
+
+        Assert.equal(
+          doc.activeElement,
+          select,
+          "The control should keep native focus behavior"
+        );
