+    }
+
+    await SpecialPowers.popPrefEnv();
+  }
+
+  doc.documentElement.removeAttribute("uidensity");
+  doc.documentElement.removeAttribute("dir");
+
+  await SpecialPowers.pushPrefEnv({
+    set: [["browser.display.document_color_use", 2]],
+  });
+
+  Assert.ok(
