diff --git a/mail/components/calendar/test/unit/test_calendarEventCalendarOptions.js b/mail/components/calendar/test/unit/test_calendarEventCalendarOptions.js
new file mode 100644
index 00000000000..6e28cde3f20
--- /dev/null
+++ b/mail/components/calendar/test/unit/test_calendarEventCalendarOptions.js
@@ -0,0 +1,291 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+"use strict";
+
+const { cal } = ChromeUtils.importESModule(
+  "resource:///modules/calendar/calUtils.sys.mjs"
+);
+const { CalEvent } = ChromeUtils.importESModule(
+  "resource:///modules/CalEvent.sys.mjs"
+);
+const { canMoveCalendarEvent, loadCalendarOptions, snapshotCalendar } =
+  ChromeUtils.importESModule(
+    "moz-src:///comm/mail/components/calendar/content/calendar-event-calendar-options.mjs"
+  );
+const { loadCalendarEventSource } = ChromeUtils.importESModule(
+  "moz-src:///comm/mail/components/calendar/content/calendar-event-source-loader.mjs"
+);
+
+const calendars = [];
+let firstCalendar;
+let defaultCalendar;
+let hiddenCalendar;
+
+/**
+ * Registers a visible memory calendar and adds it to the cleanup list.
+ *
+ * @param {string} name - The calendar name.
+ * @returns {calICalendar} The registered calendar.
+ */
+function createCalendar(name) {
+  const calendar = cal.manager.createCalendar(
+    "memory",
+    Services.io.newURI("moz-memory-calendar://")
+  );
+  calendar.name = name;
+  calendar.setProperty("calendar-main-in-composite", true);
+  cal.manager.registerCalendar(calendar);
+  calendars.push(calendar);
+  return calendar;
+}
+
+add_setup(function () {
+  do_get_profile();
+
+  const orderPref = "calendar.list.sortOrder";
+  const previousOrder = Services.prefs.prefHasUserValue(orderPref)
+    ? Services.prefs.getStringPref(orderPref)
+    : null;
+
+  registerCleanupFunction(() => {
+    for (const calendar of calendars) {
+      cal.manager.unregisterCalendar(calendar);
+    }
+    if (previousOrder === null) {
+      Services.prefs.clearUserPref(orderPref);
+    } else {
+      Services.prefs.setStringPref(orderPref, previousOrder);
+    }
+  });
+
+  firstCalendar = createCalendar("First calendar");
+  firstCalendar.setProperty("color", "#008000");
+  defaultCalendar = createCalendar("Default calendar");
+  defaultCalendar.setProperty("color", "#0000ff");
+
+  hiddenCalendar = createCalendar("Hidden calendar");
+  hiddenCalendar.setProperty("calendar-main-in-composite", false);
+  const readOnlyCalendar = createCalendar("Read only calendar");
+  readOnlyCalendar.readOnly = true;
+  const tasksCalendar = createCalendar("Tasks only calendar");
+  tasksCalendar.setProperty("capabilities.events.supported", false);
+  const disabledCalendar = createCalendar("Disabled calendar");
+  disabledCalendar.setProperty("disabled", true);
+  const noAddCalendar = createCalendar("No add permission");
+  noAddCalendar.wrappedJSObject.mACLEntry = {
+    QueryInterface: ChromeUtils.generateQI(["calICalendarACLEntry"]),
+    hasAccessControl: true,
+    userIsOwner: false,
+    userCanAddItems: false,
+  };
+});
+
+add_task(function test_snapshotCopiesOnlyDisplayData() {
+  const calendar = cal.manager.createCalendar(
+    "memory",
+    Services.io.newURI("moz-memory-calendar://")
+  );
+  calendar.id = "snapshot-calendar";
+  calendar.name = "Snapshot calendar";
+
+  Assert.deepEqual(
+    snapshotCalendar(calendar),
+    {
+      id: calendar.id,
+      name: "Snapshot calendar",
+      color: "#a8c2e1",
+    },
+    "A calendar without a color should use the fallback color"
+  );
+
+  calendar.setProperty("color", "#112233");
+  const snapshot = snapshotCalendar(calendar);
+  calendar.name = "Changed calendar";
+  calendar.setProperty("color", "#445566");
+
+  Assert.deepEqual(
+    snapshot,
+    {
+      id: calendar.id,
+      name: "Snapshot calendar",
+      color: "#112233",
+    },
+    "The snapshot should keep copied display data after the calendar changes"
+  );
+});
+
+add_task(async function test_filtersCalendarChoices() {
+  const { calendars: choices } = await loadCalendarOptions();
+
+  Assert.deepEqual(
+    choices,
+    [
+      { id: firstCalendar.id, name: "First calendar", color: "#008000" },
+      { id: defaultCalendar.id, name: "Default calendar", color: "#0000ff" },
+    ],
+    "Choices should contain only visible, writable event calendars with add permission"
+  );
+});
+
+add_task(async function test_choicesFollowListOrder() {
+  for (const [order, expected] of [
+    [
+      `${defaultCalendar.id} ${firstCalendar.id}`,
+      [defaultCalendar.id, firstCalendar.id],
+    ],
+    [
+      `missing-calendar ${defaultCalendar.id}`,
+      [defaultCalendar.id, firstCalendar.id],
+    ],
+    ["", [firstCalendar.id, defaultCalendar.id]],
+  ]) {
+    Services.prefs.setStringPref("calendar.list.sortOrder", order);
+    const { calendars: choices } = await loadCalendarOptions();
+
+    Assert.deepEqual(
+      choices.map(calendar => calendar.id),
+      expected,
+      `Choices should follow list order ${JSON.stringify(order)} and keep unlisted calendars`
+    );
+  }
+});
+
+add_task(async function test_defaultIsSeparateFromChoices() {
+  Assert.equal(
+    (await loadCalendarOptions()).defaultCalendar,
+    null,
+    "An omitted default ID should return no default calendar"
+  );
+  Assert.equal(
+    (await loadCalendarOptions("missing-calendar")).defaultCalendar,
+    null,
+    "An unknown default ID should return no default calendar"
+  );
+  Assert.deepEqual(
+    (await loadCalendarOptions(defaultCalendar.id)).defaultCalendar,
+    { id: defaultCalendar.id, name: "Default calendar", color: "#0000ff" },
+    "A supplied default ID should return its calendar display data"
+  );
+
+  const options = await loadCalendarOptions(hiddenCalendar.id);
+
+  Assert.deepEqual(
+    options.defaultCalendar,
+    { id: hiddenCalendar.id, name: "Hidden calendar", color: "#a8c2e1" },
+    "An unavailable default should retain its display data"
+  );
+  Assert.ok(
+    !options.calendars.some(calendar => calendar.id == hiddenCalendar.id),
+    "An unavailable default should stay outside the usable choices"
+  );
+});
+
+add_task(function test_moveRequiresMoreThanEditPermission() {
+  const calendarEntry = {
+    hasAccessControl: true,
+    userIsOwner: false,
+    userCanDeleteItems: true,
+  };
+  const properties = new Map([["requiresNetwork", false]]);
+  const event = {
+    recurrenceId: null,
+    recurrenceInfo: {},
+    aclEntry: { calendarEntry, userCanModify: true },
+    calendar: {
+      aclEntry: calendarEntry,
+      readOnly: false,
+      supportsScheduling: false,
+      getProperty: name => properties.get(name) ?? null,
+    },
+  };
+
+  Assert.ok(
+    canMoveCalendarEvent(event),
+    "A whole repeating event with the required permissions should permit a move"
+  );
+
+  calendarEntry.userCanDeleteItems = false;
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "Edit permission should not grant delete permission"
+  );
+
+  calendarEntry.userCanDeleteItems = true;
+  event.aclEntry.userCanModify = false;
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "Moving should require permission to modify the event"
+  );
+
+  event.aclEntry.userCanModify = true;
+  event.recurrenceId = {};
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "An editable occurrence should not permit a calendar change"
+  );
+
+  event.recurrenceId = null;
+  event.calendar.readOnly = true;
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "A read-only source calendar should prevent a move"
+  );
+
+  event.calendar.readOnly = false;
+  properties.set("disabled", true);
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "A disabled source calendar should prevent a move"
+  );
+
+  properties.delete("disabled");
+  event.calendar.supportsScheduling = true;
+  event.calendar.getSchedulingSupport = () => ({ isInvitation: () => true });
+
+  Assert.ok(
+    !canMoveCalendarEvent(event),
+    "An invitation should not permit a calendar change through the editor"
+  );
+});
+
+add_task(async function test_sourceSnapshotContainsCalendarData() {
+  const event = await firstCalendar.addItem(
+    new CalEvent(
+      [
+        "BEGIN:VEVENT",
+        "UID:calendar-options-event",
+        "SUMMARY:Saved event",
+        "DTSTART:20261020T100000Z",
+        "DTEND:20261020T110000Z",
+        "END:VEVENT",
+      ].join("\r\n")
+    )
+  );
+  const source = await loadCalendarEventSource({
+    calendarId: firstCalendar.id,
+    eventId: event.id,
+    recurrenceId: null,
+  });
+
+  Assert.deepEqual(
+    source.snapshot.calendar,
+    { id: firstCalendar.id, name: "First calendar", color: "#008000" },
+    "The loaded source should include copied calendar display data"
+  );
+  Assert.ok(
+    source.snapshot.canMoveCalendar,
+    "The loaded source should include permission to move a writable whole event"
+  );
+  Assert.deepEqual(
+    JSON.parse(JSON.stringify(source.snapshot)),
+    source.snapshot,
+    "The loaded source snapshot should contain only JSON-compatible data"
+  );
+});
diff --git a/mail/components/calendar/test/unit/test_calendarEventCalendarState.js b/mail/components/calendar/test/unit/test_calendarEventCalendarState.js
new file mode 100644
index 00000000000..48f02226031
--- /dev/null
+++ b/mail/components/calendar/test/unit/test_calendarEventCalendarState.js
@@ -0,0 +1,393 @@
+/* This Source Code Form is subject to the terms of the Mozilla Public
+ * License, v. 2.0. If a copy of the MPL was not distributed with this
+ * file, You can obtain one at http://mozilla.org/MPL/2.0/. */
+
+"use strict";
+
+const { store } = ChromeUtils.importESModule(
+  "moz-src:///comm/mail/base/content/state/store.mjs"
+);
+const {
+  changeCalendar,
+  clearCalendarSelection,
+  selectCalendarSelection,
+  setCalendarSelection,
+} = ChromeUtils.importESModule(
+  "moz-src:///comm/mail/components/calendar/content/state/calendarEventCalendarSlice.mjs"
+);
+const {
+  clearCalendarEventDraft,
+  initializeFields,
+  resetForCreate,
+  updateSection,
+} = ChromeUtils.importESModule(
+  "moz-src:///comm/mail/components/calendar/content/state/calendarEventDraftSlice.mjs"
+);
+const { selectCalendarViewModel, selectCurrentDraft, selectDirtySections } =
+  ChromeUtils.importESModule(
+    "moz-src:///comm/mail/components/calendar/content/state/calendar-event-create-edit-selectors.mjs"
+  );
+
+const sessionKey = "calendar-selection-test";
+const first = { id: "first", name: "First", color: "#ff0000" };
+const second = { id: "second", name: "Second", color: "#0000ff" };
+const otherSessionKey = `${sessionKey}-other`;
+
+add_setup(function () {
+  registerCleanupFunction(() => {
+    for (const key of [sessionKey, otherSessionKey]) {
+      store.dispatch(clearCalendarSelection({ sessionKey: key }));
+      store.dispatch(clearCalendarEventDraft({ sessionKey: key }));
+    }
+  });
+});
+
+add_task(function test_noSelectionIsDisabled() {
+  const viewModel = selectCalendarViewModel(store.getState(), sessionKey);
+
+  Assert.equal(
+    viewModel.calendar,
+    null,
+    "The calendar view should have no selection before state exists"
+  );
+  Assert.ok(
+    viewModel.disabled,
+    "The selector should be disabled before selection state exists"
+  );
+});
+
+/**
+ * Starts a create draft with two calendar choices.
+ *
+ * @param {number} generation - The operation number.
+ * @param {boolean} [canChange=true] - Whether the operation permits selection.
+ */
+function startSelection(generation, canChange = true) {
+  store.dispatch(
+    resetForCreate({ sessionKey, initialDraft: { calendarId: first.id } })
+  );
+  store.dispatch(
+    setCalendarSelection({
+      sessionKey,
+      generation,
+      canChange,
+      calendars: [first, second],
+      calendar: first,
+    })
+  );
+}
+
+add_task(function test_selectionOnlyChangesCurrentDraftCalendar() {
+  startSelection(1);
+  store.dispatch(
+    updateSection({ sessionKey, section: "title", patch: { title: "Unsaved" } })
+  );
+
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 1, calendarId: second.id })
+  );
+
+  Assert.deepEqual(
+    selectCurrentDraft(store.getState(), sessionKey),
+    { calendarId: second.id, title: "Unsaved" },
+    "The draft should contain the new calendar and the unsaved title"
+  );
+  Assert.deepEqual(
+    selectDirtySections(store.getState(), sessionKey),
+    ["title", "calendar"],
+    "The title and calendar sections should both be dirty"
+  );
+  Assert.equal(
+    store.getState().calendarEventDraft.sessions[sessionKey].baseline
+      .calendarId,
+    first.id,
+    "Calendar selection should preserve the baseline calendar"
+  );
+
+  const viewModel = selectCalendarViewModel(store.getState(), sessionKey);
+  Assert.deepEqual(
+    viewModel.calendar,
+    second,
+    "The calendar view model should contain the selected calendar data"
+  );
+  Assert.ok(
+    !viewModel.disabled,
+    "The selector should remain enabled after a calendar change"
+  );
+
+  store.dispatch(
+    updateSection({
+      sessionKey,
+      section: "title",
+      patch: { title: "Another title" },
+    })
+  );
+
+  Assert.strictEqual(
+    selectCalendarViewModel(store.getState(), sessionKey),
+    viewModel,
+    "Unrelated field changes should not rerender the calendar"
+  );
+
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 1, calendarId: first.id })
+  );
+
+  Assert.deepEqual(
+    selectDirtySections(store.getState(), sessionKey),
+    ["title"],
+    "Selecting the baseline calendar should leave only the title dirty"
+  );
+});
+
+add_task(function test_staleAndUnavailableSelectionsAreIgnored() {
+  const oldSelection = changeCalendar({
+    sessionKey,
+    generation: 1,
+    calendarId: second.id,
+  });
+
+  startSelection(2);
+  store.dispatch(oldSelection);
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey).calendarId,
+    first.id,
+    "An old operation should not change the draft calendar"
+  );
+
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 2, calendarId: "hidden" })
+  );
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey).calendarId,
+    first.id,
+    "An unavailable destination should not change the draft calendar"
+  );
+
+  startSelection(3, false);
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 3, calendarId: second.id })
+  );
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey).calendarId,
+    first.id,
+    "An operation without change permission should keep its draft calendar"
+  );
+  Assert.ok(
+    selectCalendarViewModel(store.getState(), sessionKey).disabled,
+    "The selector should be disabled when changes are denied"
+  );
+
+  store.dispatch(clearCalendarSelection({ sessionKey }));
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 3, calendarId: second.id })
+  );
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey).calendarId,
+    first.id,
+    "A selection after state is cleared should not change the draft calendar"
+  );
+});
+
+add_task(function test_fieldDefaultsPreserveOtherChanges() {
+  store.dispatch(
+    resetForCreate({ sessionKey, initialDraft: { title: "Original" } })
+  );
+  store.dispatch(
+    updateSection({ sessionKey, section: "title", patch: { title: "Unsaved" } })
+  );
+
+  store.dispatch(
+    initializeFields({ sessionKey, defaults: { calendarId: first.id } })
+  );
+
+  Assert.deepEqual(
+    selectCurrentDraft(store.getState(), sessionKey),
+    { calendarId: first.id, title: "Unsaved" },
+    "Field defaults should add the calendar and preserve the edited title"
+  );
+  Assert.deepEqual(
+    selectDirtySections(store.getState(), sessionKey),
+    ["title"],
+    "Adding field defaults should leave only the title dirty"
+  );
+  Assert.equal(
+    store.getState().calendarEventDraft.sessions[sessionKey].baseline.title,
+    "Original",
+    "Field defaults should preserve the baseline title"
+  );
+
+  store.dispatch(
+    initializeFields({ sessionKey, defaults: { calendarId: second.id } })
+  );
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey).calendarId,
+    first.id,
+    "Defaults should not replace an existing field value"
+  );
+
+  store.dispatch(clearCalendarEventDraft({ sessionKey }));
+  store.dispatch(
+    initializeFields({ sessionKey, defaults: { calendarId: second.id } })
+  );
+
+  Assert.equal(
+    selectCurrentDraft(store.getState(), sessionKey),
+    null,
+    "Field defaults should not recreate a removed draft"
+  );
+});
+
+add_task(function test_unavailableCalendarRemainsDisplayable() {
+  startSelection(4);
+  store.dispatch(
+    setCalendarSelection({
+      sessionKey,
+      generation: 4,
+      canChange: true,
+      calendars: [second],
+      calendar: first,
+    })
+  );
+
+  let viewModel = selectCalendarViewModel(store.getState(), sessionKey);
+
+  Assert.deepEqual(
+    viewModel.calendar,
+    first,
+    "An unavailable source should retain its display data"
+  );
+  Assert.ok(
+    !viewModel.disabled,
+    "An available destination should permit a change from an unavailable source"
+  );
+
+  store.dispatch(
+    setCalendarSelection({
+      sessionKey,
+      generation: 4,
+      canChange: true,
+      calendars: [],
+      calendar: first,
+    })
+  );
+  viewModel = selectCalendarViewModel(store.getState(), sessionKey);
+
+  Assert.deepEqual(
+    viewModel.calendar,
+    first,
+    "Empty choices should preserve the initial calendar display data"
+  );
+  Assert.ok(
+    viewModel.disabled,
+    "Empty choices should disable selection even when permission is granted"
+  );
+
+  store.dispatch(
+    updateSection({
+      sessionKey,
+      section: "calendar",
+      patch: { calendarId: "missing" },
+    })
+  );
+
+  Assert.equal(
+    selectCalendarViewModel(store.getState(), sessionKey).calendar,
+    null,
+    "An unknown calendar ID should have no display data"
+  );
+});
+
+add_task(function test_selectionCopiesData() {
+  startSelection(5);
+  const selection = {
+    sessionKey,
+    generation: 5,
+    canChange: true,
+    calendars: [{ ...first }, { ...second }],
+    calendar: { ...first },
+  };
+  store.dispatch(setCalendarSelection(selection));
+
+  selection.calendar.name = "Changed source";
+  selection.calendars[0].name = "Changed choice";
+  selection.calendars.push({ id: "extra", name: "Extra", color: "#ffffff" });
+
+  const saved = selectCalendarSelection(store.getState(), sessionKey);
+
+  Assert.deepEqual(
+    saved.calendar,
+    first,
+    "Stored source data should not change with the action payload"
+  );
+  Assert.deepEqual(
+    saved.calendars,
+    [first, second],
+    "Stored choices should not change with the action payload"
+  );
+
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 5, calendarId: second.id })
+  );
+  const { calendarEventCalendar, calendarEventDraft } = store.getState();
+  const state = { calendarEventCalendar, calendarEventDraft };
+
+  Assert.deepEqual(
+    JSON.parse(JSON.stringify(state)),
+    state,
+    "Selection and draft state should contain only JSON-compatible data"
+  );
+});
+
+add_task(function test_sessionsRemainIsolated() {
+  startSelection(6);
+  store.dispatch(
+    resetForCreate({
+      sessionKey: otherSessionKey,
+      initialDraft: { calendarId: first.id, title: "Other draft" },
+    })
+  );
+  store.dispatch(
+    setCalendarSelection({
+      sessionKey: otherSessionKey,
+      generation: 6,
+      canChange: true,
+      calendars: [first, second],
+      calendar: first,
+    })
+  );
+
+  store.dispatch(
+    changeCalendar({ sessionKey, generation: 6, calendarId: second.id })
+  );
+
+  Assert.deepEqual(
+    selectCurrentDraft(store.getState(), otherSessionKey),
+    { calendarId: first.id, title: "Other draft" },
+    "A calendar change should leave another session's draft unchanged"
+  );
+
+  store.dispatch(clearCalendarSelection({ sessionKey }));
+  store.dispatch(clearCalendarEventDraft({ sessionKey }));
+
+  Assert.equal(
+    selectCalendarSelection(store.getState(), sessionKey),
+    null,
+    "Clearing a session should remove its calendar selection"
+  );
+  Assert.deepEqual(
+    selectCalendarViewModel(store.getState(), otherSessionKey).calendar,
+    first,
+    "Clearing a session should preserve another session's calendar selection"
+  );
+  Assert.deepEqual(
+    selectCurrentDraft(store.getState(), otherSessionKey),
+    { calendarId: first.id, title: "Other draft" },
+    "Clearing a session should preserve another session's draft"
+  );
+});
